    return [(item_id, parse_tags(raw_tags)) for item_id, raw_tags in raw_data]


def iterative_stratification(data, seed=42):
    n = len(data)
    rng = random.Random(seed)
    shuffled = data.copy()
    rng.shuffle(shuffled)

    # Group by tag set (label combination)
    by_combo = defaultdict(list)
    for i, (item_id, tags) in enumerate(shuffled):
        by_combo[tags].append(i)

    # Sort combos by frequency (rarest first)
    sorted_combos = sorted(by_combo.keys(), key=lambda c: (len(by_combo[c]), str(c)))

    # Target sizes
    target_train = int(n * 0.7)
    target_val = int(n * 0.15)
    target_test = n - target_train - target_val

    train_ids, val_ids, test_ids = [], [], []
    cur_train, cur_val, cur_test = 0, 0, 0

    for combo in sorted_combos:
        indices = by_combo[combo]
        n_combo = len(indices)

        # Remaining capacity
        rem_train = target_train - cur_train
        rem_val = target_val - cur_val
        rem_test = target_test - cur_test
        total_rem = rem_train + rem_val + rem_test

        if total_rem <= 0:
            # All splits full, assign to train
            for idx in indices:
                train_ids.append(shuffled[idx][0])
            continue

        # Proportional assignment based on remaining needs
        # Use exact proportions then adjust
        frac_train = rem_train / total_rem
        frac_val = rem_val / total_rem
        frac_test = rem_test / total_rem

        # Compute counts using round for better distribution
        n_train = int(round(n_combo * frac_train))
        n_val = int(round(n_combo * frac_val))
        n_test = n_combo - n_train - n_val

        # Adjust to not exceed remaining capacity
        # First cap each
        n_train = min(n_train, rem_train)
        n_val = min(n_val, rem_val)
        n_test = min(n_test, rem_test)

        # If sum is less than n_combo, distribute remainder
        assigned = n_train + n_val + n_test
        if assigned < n_combo:
            remaining = n_combo - assigned
            # Add to split with most remaining capacity
            if rem_train >= rem_val and rem_train >= rem_test:
                n_train += remaining
            elif rem_val >= rem_test:
                n_val += remaining
            else:
                n_test += remaining

        # Assign
        for i, idx in enumerate(indices):
            if i < n_train:
                train_ids.append(shuffled[idx][0])
            elif i < n_train + n_val:
                val_ids.append(shuffled[idx][0])
            else:
                test_ids.append(shuffled[idx][0])

        cur_train += n_train
        cur_val += n_val
        cur_test += n_test

    return train_ids, val_ids, test_ids


