    raw_data = read_input(input_path)
    return [(item_id, parse_tags(raw_tags)) for item_id, raw_tags in raw_data]


def iterative_stratification(data, seed=42):
    """
    Iterative stratification: shuffle once, then assign samples to splits
    by processing label combinations from rarest to most common.
    """
    n = len(data)
    rng = random.Random(seed)

    # Shuffle data with seed - this determines processing order
    shuffled = data.copy()
    rng.shuffle(shuffled)

    # Compute target counts
    target_train = int(n * 0.7)
    target_val = int(n * 0.15)
    target_test = n - target_train - target_val

